const q = ($input.first().json.query) || {};
let challenge = 'forbidden';
if (q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === $env.WHATSAPP_VERIFY_TOKEN) { challenge = q['hub.challenge']; }
return [{ json: { challenge } }];

const inp = $input.first().json;
const body = inp.body || inp;
let out = { isMessage: false };
try {
  const value = body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0] && body.entry[0].changes[0].value;
  const msg = value && value.messages && value.messages[0];
  if (msg) {
    out = { isMessage: true,
      phone_number_id: value.metadata && value.metadata.phone_number_id,
      from: msg.from, msgId: msg.id,
      text: (msg.text && msg.text.body) || (msg.button && msg.button.text) || (msg.interactive && msg.interactive.button_reply && msg.interactive.button_reply.title) || '' };
  }
} catch (e) {}
return [{ json: out }];

const p = $('Parse').first().json;
if (!p.isMessage) return [];
const esc = (s) => String(s == null ? '' : s).replace(/'/g, "''");
const pnid = esc(p.phone_number_id);
const from = esc(p.from);
const sql = `
with cl as (select id, name, timezone, google_calendar_id from clinics where phone_number_id = '${pnid}'),
pat as (insert into patients (clinic_id, whatsapp_number) select cl.id, '${from}' from cl
  on conflict (clinic_id, whatsapp_number) do update set whatsapp_number = excluded.whatsapp_number returning id, clinic_id),
con as (insert into conversations (clinic_id, patient_id, status, last_message_at) select pat.clinic_id, pat.id, 'bot', now() from pat
  on conflict (clinic_id, patient_id) do update set last_message_at = now() returning id, status)
select cl.name as clinic_name, cl.timezone, cl.google_calendar_id, pat.id as patient_id, con.id as conversation_id, con.status
from cl, pat, con;`;
return [{ json: { sql } }];

const r = $input.first().json;
const parse = $('Parse').first().json;
const msg = (r.choices && r.choices[0] && r.choices[0].message) || {};
let reply;
if (msg.tool_calls && msg.tool_calls.length) {
  const name = msg.tool_calls[0].function.name;
  reply = (name === 'escalate_to_human')
    ? "I'm getting a team member to help you right away — they'll reply here shortly."
    : "Let me check our calendar and get right back to you 🙂";
} else { reply = msg.content || "Sorry, could you say that another way?"; }
return [{ json: { to: parse.from, reply: reply, phone_number_id: parse.phone_number_id } }];
